/* eslint-disable no-console */
/**
 * P4-023 — تصدير المجموعة المرجعية المجمدة لمعيار دمج الكيانات.
 * The reference set of record: the SAME frozen synthetic set the core/er
 * acceptance protocol uses (seed 1337 eval; seed 42 train) — generated by the
 * engine's own deterministic generator (no dataset invention here). Every
 * benchmarked tool gets the same splits and is judged by the same pairwise F1.
 */
import { generateReferenceSet } from "../../packages/core/src/er/reference-set.ts";
import { writeFileSync, mkdirSync } from "node:fs";

mkdirSync(new URL("./data/", import.meta.url), { recursive: true });
const train = generateReferenceSet(42);
const evalSet = generateReferenceSet(1337);

const row = (r) => ({
  id: r.id,
  name: r.name,
  country: r.country,
  birthDate: r.birthDate ?? null,
  addresses: r.addresses.length ? r.addresses.join(" | ") : null,
  identifiers: r.identifiers.length ? r.identifiers.join(" | ") : null,
});
writeFileSync(new URL("./data/records-train.json", import.meta.url), JSON.stringify(train.train.records.map(row)));
writeFileSync(new URL("./data/records-eval.json", import.meta.url), JSON.stringify(evalSet.eval.records.map(row)));
writeFileSync(
  new URL("./data/truth-eval.json", import.meta.url),
  JSON.stringify(evalSet.eval.duplicatePairs.map((p) => [p.a.id, p.b.id].sort())),
);
writeFileSync(
  new URL("./data/labels-train.json", import.meta.url),
  JSON.stringify({
    positives: train.train.duplicatePairs.map((p) => [p.a.id, p.b.id].sort()),
  }),
);
console.log(`train records: ${train.train.records.length}, train positive pairs: ${train.train.duplicatePairs.length}`);
console.log(`eval records: ${evalSet.eval.records.length}, eval positive pairs: ${evalSet.eval.duplicatePairs.length}`);
